import{z as o,x as A,o as r,c as B,q as l,j as n,D as s,d as E,s as i,S as p,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"SparseGPT","description":"","frontmatter":{"title":"SparseGPT","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sparsegpt.md","filePath":"llm/sparsegpt.md","lastUpdated":1791063341000}'),d={name:"llm/sparsegpt.md"};function m(u,a,P,T,D,h){const t=A("Mermaid");return r(),B("div",null,[a[2]||(a[2]=l('<h1 id="sparsegpt" tabindex="-1">SparseGPT <a class="header-anchor" href="#sparsegpt" aria-label="Permalink to &quot;SparseGPT&quot;">​</a></h1><div class="epigraph"><p>把 GPTQ 的二阶补偿从「取整」改成「置零」：一层之内决定哪些权重留下，并把删掉的质量 squirt 到留下的值上。千亿参数可以剪完，而不必再训完。</p><footer>—— Frantar &amp; Alistarh, SparseGPT: Massive Language Models Can Be Accurately Pruned in One-Shot, ICML 2023</footer></div><p><a href="/llm/quant-eval-degradation">量化退化</a> 收束了 PTQ 基础。本课打开稀疏单元： <strong>SparseGPT</strong>。<a href="/llm/unstructured-sparsity">非结构化稀疏</a> 已写掩码与核的鸿沟；<a href="/llm/gptq">GPTQ</a> 已写 Hessian 补偿。缺口是一次性剪枝如何借用同一套 \\(\\min\\|\\hat W X-WX\\|\\)，约束从格子换成硬零。后课 Wanda 会丢掉二阶、只留幅度×激活；本课先把完整重建立住。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>幅度剪枝假设 \\(|w|\\) 小则不重要。LLM 里小权重乘大激活可以很重要。OBQ 式剪枝每步挑最不疼的权重，规模不可行。SparseGPT 要：一次前向校准、逐层、能跑 175B、掩码非结构（或块结构）。问题与 GPTQ 平行，离散动作从 round 变成 prune。</p><p>没有稀疏核时，墙钟不变，只省存储（还要付索引）。本课主质量；<a href="/llm/two-four-sparsity">2:4</a> 再谈加速。不要用论文稀疏度乘量化 bit 当加速比，分工课已禁。</p><p><span class="marginnote">One-shot 指不必迭代重训到收敛，不是指零校准。校准 \\(X\\) 仍然关键，过拟合同样发生。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对一层，用校准 \\(X\\) 构 Hessian \\(\\sim XX^\\top\\)。按列（或块）选择保留集合（满足稀疏度或 N:M），置零的位置把残差经 Hessian 逆补偿到未处理权重——与 GPTQ 同一 squirt，动作是零而不是台阶。列序固定以保证复杂度。量化可以在同一框架后接（先剪再量化要重校准）。</p><p><span class="marginnote">直觉类比：拔掉一根承重的钉子，横梁会塌一点；SparseGPT 不是只拔钉子（置零），而是顺手把旁边没拔的钉子都拧紧一点（补偿），让横梁还停在原位。只记录「哪些钉子拔了」而丢掉「拧紧的量」，质量就塌回普通的幅度剪枝。</span></p>',10)),(r(),n(p,null,{default:s(()=>[i(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E6%A0%A1%E5%87%86%20X%22%5D%20--%3E%20H%5B%22Hessian%22%5D%0A%20%20W%5B%22%E7%A8%A0%E5%AF%86%20W%22%5D%20--%3E%20SEL%5B%22%E6%8C%89%E5%88%97%E9%80%89%E4%BF%9D%E7%95%99%E4%BD%8D%22%5D%0A%20%20H%20--%3E%20SEL%0A%20%20SEL%20--%3E%20Z%5B%22%E7%BD%AE%E9%9B%B6%22%5D%0A%20%20Z%20--%3E%20CMP%5B%22%E8%A1%A5%E5%81%BF%E5%89%A9%E4%BD%99%E9%9D%9E%E9%9B%B6%22%5D%0A%20%20CMP%20--%3E%20M%5B%22%E7%A8%80%E7%96%8F%20W%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"实现上掩码非结构，部署若要 2:4，应在选择阶段就加 N:M 约束，而不是剪完再硬塞模式。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"数字实例：50% 稀疏的 175B 模型仍有约 875 亿个非零权重，而且稀疏存储还要额外付「记录哪些位置非零」的索引。2:4 这类模式用「每 4 个留 2 个」的固定间隔把索引开销压到约零——这就是结构化稀疏存在的理由。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"二次型与 GPTQ 相同：删掉的自由度变成等式约束（值为 0），牛顿步在剩余子空间减小重建误差。所以「剪完权重看起来变了」是功能：留下的值不是原值。只存掩码不存更新后的非零，会丢掉补偿，质量回到笨幅度剪。",-1)),(r(),n(p,null,{default:s(()=>[i(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20Z%5B%22%E6%9F%90%E4%B8%AA%E6%9D%83%E9%87%8D%E8%A2%AB%E7%BD%AE%E9%9B%B6%22%5D%20--%3E%20RES%5B%22%E5%B1%82%E8%BE%93%E5%87%BA%E5%87%BA%E7%8E%B0%E9%87%8D%E5%BB%BA%E8%AF%AF%E5%B7%AE%22%5D%0A%20%20RES%20--%3E%20HINV%5B%22%E6%B2%BF%20Hessian%20%E9%80%86%E7%AE%97%E5%87%BA%E6%9C%80%E8%AF%A5%E8%A1%A5%E7%9A%84%E4%BD%8D%E7%BD%AE%22%5D%0A%20%20HINV%20--%3E%20OTHER%5B%22%E8%A1%A5%E5%81%BF%E9%87%8F%E5%8A%A0%E5%88%B0%E6%9C%AC%E5%B1%82%E6%9C%AA%E5%A4%84%E7%90%86%E7%9A%84%E6%9D%83%E9%87%8D%E4%B8%8A%22%5D%0A%20%20OTHER%20--%3E%20EQ%5B%22%E6%A0%A1%E5%87%86%E6%95%B0%E6%8D%AE%E4%B8%8A%E5%B1%82%E8%BE%93%E5%87%BA%E4%BB%8D%E8%BF%91%E4%BC%BC%E5%8E%9F%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p>校准域决定哪些方向被当成「能量」。换域后，为网页 PPL 保住的连接可能不是代码需要的。签字用分能力，同量化课。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要期望 50% 非结构在 GPU 上加速。不要把 SparseGPT 检查点当 QAT 稀疏的初始化而不看补偿后的值。不要与 Wanda 比而不锁校准与稀疏度。下一课 Wanda：更便宜的打分，无完整 squirt。</p><p><span class="marginnote">常见误区：把「50% 稀疏」直接换算成「2 倍加速」。非结构化掩码在没有配套稀疏核的 GPU 上一个 FLOP 都省不了——墙钟不变，只省磁盘；只有 2:4 这种硬件认识的固定模式，稀疏才可能兑现成吞吐。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SparseGPT：一层重建 + Hessian 补偿的一次性剪枝，动作是置零。</li><li>留下的非零已被更新；只存掩码会丢补偿。</li><li>质量路径与 GPTQ 同源，核路径仍取决于结构约束。</li><li>校准过拟合与分能力验收同量化纪律。</li><li>出处：Frantar &amp; Alistarh, ICML 2023 SparseGPT。</li></ul>',6))])}const g=o(d,[["render",m]]);export{S as __pageData,g as default};
